var objects=UnityEngine.Object.FindObjectsByType<ObstacleStats>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None);
string Path(Transform t)=>t.parent==null?t.name:Path(t.parent)+"/"+t.name;
return new{total=objects.Length,active=objects.Count(o=>o.gameObject.activeInHierarchy),nearEarlyDeath=objects.Where(o=>Vector3.ProjectOnPlane(o.transform.position-new Vector3(-10,0,-30),Vector3.up).magnitude<40).Select(o=>new{path=Path(o.transform),o.value,pattern=o.obstaclePattern.ToString(),pos=o.transform.position.ToString(),active=o.gameObject.activeInHierarchy,colliders=o.GetComponentsInChildren<Collider>(true).Select(c=>new{path=Path(c.transform),c.enabled,c.isTrigger,center=c.bounds.center.ToString(),size=c.bounds.size.ToString()}).ToArray()}).ToArray()};
